class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        a, b = sorted(nums1), sorted(nums2)
        def ok(x):
            j = skip = 0
            for v in a:
                if j < len(b) and v + x == b[j]:
                    j += 1
                else:
                    skip += 1
            return j == len(b) and skip == 2
        best = None
        for i in range(3):
            x = b[0] - a[i]
            if ok(x) and (best is None or x < best):
                best = x
        return best

