class Solution {
public:
    int minimumAddedInteger(vector<int>& nums1, vector<int>& nums2) {
        vector<int> a = nums1, b = nums2;
        sort(a.begin(), a.end()); sort(b.begin(), b.end());
        auto ok = [&](long long x) {
            int j = 0, skip = 0;
            for (int v : a) {
                if (j < (int)b.size() && v + x == b[j]) j++;
                else skip++;
            }
            return j == (int)b.size() && skip == 2;
        };
        int best = INT_MAX;
        for (int i = 0; i < 3; i++) {
            long long x = (long long)b[0] - a[i];
            if (ok(x)) best = min(best, (int)x);
        }
        return best;
    }
};

