class Solution {
    public int minimumAddedInteger(int[] nums1, int[] nums2) {
        int[] a = nums1.clone(), b = nums2.clone();
        Arrays.sort(a); Arrays.sort(b);
        int best = Integer.MAX_VALUE;
        for (int i = 0; i < 3; i++) {
            final int x = b[0] - a[i];
            int j = 0, skip = 0;
            for (int v : a) {
                if (j < b.length && v + x == b[j]) j++;
                else skip++;
            }
            if (j == b.length && skip == 2) best = Math.min(best, x);
        }
        return best;
    }
}

