class Solution:
    def minimumAddedInteger(self, nums1: List[int], nums2: List[int]) -> int:
        from collections import Counter
        target = Counter(nums2)
        best = None
        n = len(nums1)
        for p in range(n):
            for q in range(p + 1, n):
                rem = Counter(nums1) - Counter([nums1[p], nums1[q]])
                x = min(nums2) - min(rem)
                if all(rem[v - x] == c for v, c in target.items()) and sum(rem.values()) == len(nums2):
                    if best is None or x < best:
                        best = x
        return best

