class Solution {
public:
    int minimumAddedInteger(vector<int>& nums1, vector<int>& nums2) {
        map<int,int> target;
        for (int v : nums2) target[v]++;
        int best = INT_MAX;
        int n = nums1.size();
        for (int p = 0; p < n; p++) for (int q = p + 1; q < n; q++) {
            map<int,int> rem;
            for (int i = 0; i < n; i++) if (i != p && i != q) rem[nums1[i]]++;
            int mn = INT_MAX;
            for (auto& kv : rem) mn = min(mn, kv.first);
            long long x = (long long)*min_element(nums2.begin(), nums2.end()) - mn;
            bool ok = true;
            for (auto& kv : target)
                if (rem[kv.first - (int)x] != kv.second) { ok = false; break; }
            if (ok) best = min(best, (int)x);
        }
        return best;
    }
};

