class Solution {
    public int minimumAddedInteger(int[] nums1, int[] nums2) {
        Map<Integer,Integer> target = new HashMap<>();
        for (int v : nums2) target.merge(v, 1, Integer::sum);
        int mn2 = Arrays.stream(nums2).min().getAsInt();
        int best = Integer.MAX_VALUE, n = nums1.length;
        for (int p = 0; p < n; p++) for (int q = p + 1; q < n; q++) {
            Map<Integer,Integer> rem = new HashMap<>();
            int mn = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) if (i != p && i != q) {
                rem.merge(nums1[i], 1, Integer::sum);
                mn = Math.min(mn, nums1[i]);
            }
            int x = mn2 - mn;
            boolean ok = true;
            for (Map.Entry<Integer,Integer> e : target.entrySet())
                if (rem.getOrDefault(e.getKey() - x, 0) != e.getValue()) { ok = false; break; }
            if (ok) best = Math.min(best, x);
        }
        return best;
    }
}

