    const target = new Map();
    for (const v of nums2) target.set(v, (target.get(v) || 0) + 1);
    const mn2 = Math.min(...nums2);
    let best = null;
    const n = nums1.length;
    for (let p = 0; p < n; p++) for (let q = p + 1; q < n; q++) {
        const rem = new Map(); let mn = Infinity;
        for (let i = 0; i < n; i++) if (i !== p && i !== q) {
            rem.set(nums1[i], (rem.get(nums1[i]) || 0) + 1);
            mn = Math.min(mn, nums1[i]);
        }
        const x = mn2 - mn;
        let ok = true;
        for (const [v, c] of target) if ((rem.get(v - x) || 0) !== c) { ok = false; break; }
        if (ok && (best === null || x < best)) best = x;
    }
    return best;
};
